body {
  background-color: #f5f6f8;
  color: #18181b;
  font-family: system-ui, "Segoe UI", sans-serif;
  line-height: 1.6;
  padding: 16px;
}

h1 { font-size: 26px; }

#output {
  list-style: none;
  padding: 0;
  max-width: 520px;
}

#output li {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;
  background-color: #ffffff;
  border-radius: 8px;
  padding: 10px 14px;
  margin-bottom: 8px;
}

#output span { color: #3f3f46; font-size: 14px; }

#output code {
  font-family: ui-monospace, "Cascadia Mono", monospace;
  font-weight: 700;
  color: #1d4ed8;
}

// Shop.mn — TypeScript.
// Preview нь төрлийг хуулаад ажиллуулна; «Шалгах» дарахад ЖИНХЭНЭ TypeScript
// хөрвүүлэгч төрлүүдийг чинь шалгана.

// энд бичнэ үү
function wrap(data) {
  return { ok: true, data: data };
}

function pluck(item, key) {
  return item[key];
}

// Tier 1-д модуль байхгүй тул функцүүдээ ил гаргана.
(globalThis as unknown as Record<string, unknown>).SHOP = { wrap, pluck };

// Үр дүнг харуулах жижиг самбар. Энэ файлыг өөрчлөх шаардлагагүй.

const output = document.getElementById("output");

function row(label, value) {
  const line = document.createElement("li");
  const name = document.createElement("span");
  name.textContent = label;
  const result = document.createElement("code");
  result.textContent = value;
  line.append(name, result);
  output.append(line);
}

(function () {
  const shop = window.SHOP || {};
  window.OUT = {};

  const items = [
    { id: 1, name: "Монгол дээл", price: 129000, quantity: 2 },
    { id: 2, name: "Малгай", price: 45000, quantity: 1 },
  ];

  try {
    if (typeof shop.wrap === "function") {
      const res = shop.wrap(items);
      window.OUT.wrappedOk = res.ok;
      window.OUT.count = res.data.length;
      row("wrap(items).ok", String(window.OUT.wrappedOk));
      row("wrap(items).data.length", String(window.OUT.count));
    }

    if (typeof shop.pluck === "function") {
      window.OUT.firstName = shop.pluck(items[0], "name");
      window.OUT.firstPrice = shop.pluck(items[0], "price");
      row('pluck(items[0], "name")', String(window.OUT.firstName));
      row('pluck(items[0], "price")', String(window.OUT.firstPrice));
    }
  } catch (problem) {
    row("алдаа", problem.message);
  }

  document.body.dataset.ready = "1";
})();

