// Shop.mn — TypeScript.
// Preview нь төрлийг хуулаад ажиллуулна; «Шалгах» дарахад ЖИНХЭНЭ TypeScript
// хөрвүүлэгч төрлүүдийг чинь шалгана.

interface ApiResult<T> {
  ok: boolean;
  data: T;
}

function wrap<T>(data: T): ApiResult<T> {
  return { ok: true, data };
}

function pluck<T, K extends keyof T>(item: T, key: K): T[K] {
  return item[key];
}

// Tier 1-д модуль байхгүй тул функцүүдээ ил гаргана.
(globalThis as unknown as Record<string, unknown>).SHOP = { wrap, pluck };
